{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);`);
// Existing databases predate archive support; retain their projects and tasks.
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
const listTasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const findTask = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const taskJson = task => ({ ...task, completed: Boolean(task.completed) });
const projectSelect = `SELECT p.id, p.name, p.archived,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectSelect} ORDER BY p.id`);
const findProject = db.prepare(`${projectSelect} WHERE p.id = ?`);
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const archiveProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const projectJson = project => ({ ...project, archived: Boolean(project.archived) });

const assets = new Map([
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/style.css', ['style.css', 'text/css; charset=utf-8']],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && request.method === 'GET') {
      return json(response, 200, listProjects.all().map(projectJson));
    }
    if (path === '/api/projects' && request.method === 'POST') {
      const body = await readJson(request);
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectJson(findProject.get(Number(result.lastInsertRowid))));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const projectId = Number(tasksMatch[1]);
      const taskId = tasksMatch[2] ? Number(tasksMatch[2]) : null;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project cannot be changed' });
      }
      if (taskId === null && request.method === 'GET') {
        return json(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (taskId === null && request.method === 'POST') {
        const body = await readJson(request);
        const title = typeof body?.title === 'string' ? body.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title);
        return json(response, 201, taskJson(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (taskId !== null && request.method === 'PATCH') {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const body = await readJson(request);
        if (Object.hasOwn(body ?? {}, 'title')) {
          if (Object.hasOwn(body, 'completed')) {
            return json(response, 400, { error: 'Rename and completion must be separate changes' });
          }
          const title = typeof body.title === 'string' ? body.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else {
          if (typeof body?.completed !== 'boolean') {
            return json(response, 400, { error: 'Task completion must be a boolean' });
          }
          updateTask.run(Number(body.completed), projectId, taskId);
        }
        return json(response, 200, taskJson(findTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (projectMatch && ['GET', 'PATCH'].includes(request.method)) {
      const projectId = Number(projectMatch[1]);
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'PATCH') {
        const body = await readJson(request);
        if (Object.hasOwn(body ?? {}, 'name')) {
          if (Object.hasOwn(body, 'archived')) {
            return json(response, 400, { error: 'Rename and archive must be separate changes' });
          }
          if (project.archived) {
            return json(response, 409, { error: 'Archived project cannot be changed' });
          }
          const name = typeof body.name === 'string' ? body.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, projectId);
        } else {
          if (typeof body?.archived !== 'boolean') {
            return json(response, 400, { error: 'Project archive state must be a boolean' });
          }
          archiveProject.run(Number(body.archived), projectId);
        }
      }
      return json(response, 200, projectJson(findProject.get(projectId)));
    }
    if (request.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path) || assets.has(path))) {
      const [file, contentType] = assets.get(path) || ['index.html', 'text/html; charset=utf-8'];
      const contents = await readFile(new URL(`./public/${file}`, import.meta.url));
      response.writeHead(200, { 'Content-Type': contentType });
      return response.end(contents);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Request failed');
  return body;
}

function projectsButton() {
  const button = element('button', 'Projects');
  button.type = 'button';
  button.addEventListener('click', () => location.assign('/'));
  return button;
}

function projectRow(project, onArchive) {
  const row = element('li');
  row.dataset.testid = 'project-row';
  const button = element('button', 'Open project');
  button.type = 'button';
  button.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const summary = element('span', `${project.completed}/${project.total} completed`);
  summary.dataset.testid = 'project-summary';
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
  archive.type = 'button';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, updated);
      app.querySelector('[role="alert"]')?.remove();
      onArchive();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(element('span', project.name), summary, button, archive);
  return row;
}

function renderRename(project, heading) {
  const form = element('form');
  const label = element('label', 'New project name');
  label.htmlFor = 'new-project-name';
  const input = element('input');
  input.id = 'new-project-name';
  input.name = 'name';
  input.type = 'text';
  input.disabled = project.archived;
  const submit = element('button', 'Rename project');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(label, input, submit);
  app.append(form);

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    if (!input.value.trim()) {
      showError('Project name is required');
      return;
    }
    submit.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      Object.assign(project, updated);
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
}

function taskRenameForm(project, task, endpoint, onRename) {
  const form = element('form');
  const label = element('label', 'New task title');
  const input = element('input');
  input.id = `new-task-title-${task.id}`;
  label.htmlFor = input.id;
  input.name = 'title';
  input.type = 'text';
  input.disabled = project.archived;
  const submit = element('button', 'Rename task');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(label, input, submit);

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    if (!input.value.trim()) {
      showError('Task title is required');
      return;
    }
    submit.disabled = true;
    try {
      const updated = await request(`${endpoint}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      });
      task.title = updated.title;
      app.querySelector('[role="alert"]')?.remove();
      onRename();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
  return form;
}

async function renderTasks(project) {
  const endpoint = `/api/projects/${project.id}/tasks`;
  const form = element('form');
  const titleLabel = element('label', 'Task title');
  titleLabel.htmlFor = 'task-title';
  const input = element('input');
  input.id = 'task-title';
  input.name = 'title';
  input.type = 'text';
  const submit = element('button', 'Create task');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(titleLabel, input, submit);

  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const name of ['All', 'Open', 'Completed']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  const filterControls = element('div');
  filterControls.className = 'task-filter';
  filterControls.append(filterLabel, filter);
  const list = element('ul');
  list.setAttribute('aria-label', 'Tasks');
  app.append(form, filterControls, list);
  const tasks = await request(endpoint);

  function displayTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      const row = element('li');
      row.dataset.testid = 'task-row';
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        try {
          const updated = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = updated.completed;
          app.querySelector('[role="alert"]')?.remove();
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error.message);
        } finally {
          checkbox.disabled = project.archived;
        }
      });
      row.append(element('span', task.title), checkbox,
        taskRenameForm(project, task, endpoint, displayTasks));
      list.append(row);
    }
  }
  filter.addEventListener('change', displayTasks);
  displayTasks();

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    if (!input.value.trim()) {
      showError('Task title is required');
      return;
    }
    submit.disabled = true;
    try {
      const task = await request(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      });
      tasks.push(task);
      displayTasks();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
}

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.append(projectsButton());
    const project = await request(`/api/projects/${match[1]}`);
    document.title = `${project.name} · Workboard`;
    const heading = element('h1', project.name);
    app.append(heading);
    if (project.archived) app.append(element('p', 'Archived project'));
    renderRename(project, heading);
    await renderTasks(project);
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  form.append(label, input, submit);
  const list = element('ul');
  list.setAttribute('aria-label', 'Projects');
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const name of ['Active', 'Archived']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  const filterControls = element('div');
  filterControls.className = 'task-filter';
  filterControls.append(filterLabel, filter);
  app.append(form, filterControls, list);
  const projects = await request('/api/projects');
  function displayProjects() {
    list.replaceChildren();
    for (const project of projects) {
      if (project.archived === (filter.value === 'Archived')) {
        list.append(projectRow(project, displayProjects));
      }
    }
  }
  filter.addEventListener('change', displayProjects);
  displayProjects();

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (!input.value.trim()) {
      showError('Project name is required');
      return;
    }
    submit.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      projects.push(project);
      displayProjects();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = false;
    }
  });
}

render().catch(error => showError(error.message)).finally(() => {
  app.setAttribute('aria-busy', 'false');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';
import { DatabaseSync } from 'node:sqlite';

async function availablePort() {
  const socket = net.createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise(resolve => socket.close(resolve));
  return port;
}

async function start(port, database) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: String(port), DB_PATH: database },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  child.stderr.on('data', chunk => { output += chunk; });
  const base = `http://127.0.0.1:${port}`;
  for (let attempt = 0; attempt < 100; attempt++) {
    if (child.exitCode !== null) throw new Error(output);
    try {
      const response = await fetch(`${base}/health`);
      if (response.ok) return { child, base };
    } catch { /* Wait for the server to bind. */ }
    await new Promise(resolve => setTimeout(resolve, 20));
  }
  child.kill();
  throw new Error(`Server did not start: ${output}`);
}

async function stop(child) {
  const exit = once(child, 'exit');
  child.kill('SIGTERM');
  await exit;
}

test('renaming preserves identity, order, tasks and summaries across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-rename-'));
  const database = join(directory, 'projects.sqlite');
  const port = await availablePort();
  let running;
  try {
    running = await start(port, database);
    const get = async path => (await fetch(`${running.base}${path}`)).json();
    const mutate = (path, method, body) => fetch(`${running.base}${path}`, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const first = await (await mutate('/api/projects', 'POST', { name: 'Original' })).json();
    const second = await (await mutate('/api/projects', 'POST', { name: 'Second' })).json();
    const path = `/api/projects/${first.id}`;
    const tasksPath = `${path}/tasks`;
    const task = await (await mutate(tasksPath, 'POST', { title: 'Keep this task' })).json();
    await mutate(`${tasksPath}/${task.id}`, 'PATCH', { completed: true });
    const original = { ...first, completed: 1, total: 1 };
    for (const name of ['', ' \t\n ', null, 42]) {
      const response = await mutate(path, 'PATCH', { name });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
      assert.deepEqual(await get(path), original);
    }
    const renamed = { ...original, name: 'Renamed project' };
    const response = await mutate(path, 'PATCH', { name: '  Renamed project  ' });
    assert.equal(response.status, 200);
    assert.deepEqual(await response.json(), renamed);
    assert.deepEqual(await get('/api/projects'), [renamed, second]);
    assert.deepEqual(await get(tasksPath), [{ ...task, completed: true }]);
    assert.equal((await fetch(`${running.base}/projects/${first.id}`)).status, 200);
    assert.equal((await mutate('/api/projects/99999', 'PATCH', { name: 'Missing' })).status, 404);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await get('/api/projects'), [renamed, second]);
    await mutate(path, 'PATCH', { archived: true });
    assert.equal((await mutate(path, 'PATCH', { name: 'Forbidden' })).status, 409);
    assert.equal((await mutate(path, 'PATCH', { name: 'Forbidden', archived: false })).status, 400);
    assert.deepEqual(await get(path), { ...renamed, archived: true });
    await stop(running.child);
    running = await start(port, database);
    assert.equal((await mutate(path, 'PATCH', { name: 'Still forbidden' })).status, 409);
    await mutate(path, 'PATCH', { archived: false });
    const restored = { ...renamed, name: 'Restored and renamed' };
    assert.deepEqual(await (await mutate(path, 'PATCH', { name: ' Restored and renamed ' })).json(), restored);
    assert.deepEqual(await get(tasksPath), [{ ...task, completed: true }]);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await get('/api/projects'), [restored, second]);
    assert.deepEqual(await get(tasksPath), [{ ...task, completed: true }]);
  } finally {
    if (running && running.child.exitCode === null) await stop(running.child);
    await rm(directory, { recursive: true, force: true });
  }
});

test('task renaming preserves completion, ownership, order and summaries across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-task-rename-'));
  const database = join(directory, 'projects.sqlite');
  const port = await availablePort();
  let running;
  try {
    running = await start(port, database);
    const get = async path => (await fetch(`${running.base}${path}`)).json();
    const mutate = (path, method, body) => fetch(`${running.base}${path}`, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const project = await (await mutate('/api/projects', 'POST', { name: 'First' })).json();
    const other = await (await mutate('/api/projects', 'POST', { name: 'Other' })).json();
    const projectPath = `/api/projects/${project.id}`;
    const tasksPath = `${projectPath}/tasks`;
    const otherTasksPath = `/api/projects/${other.id}/tasks`;
    const task = await (await mutate(tasksPath, 'POST', { title: 'Original' })).json();
    const second = await (await mutate(tasksPath, 'POST', { title: 'Second' })).json();
    const taskPath = `${tasksPath}/${task.id}`;
    await mutate(taskPath, 'PATCH', { completed: true });
    const completed = { ...task, completed: true };
    const summary = { ...project, completed: 1, total: 2 };
    for (const title of ['', ' \t\n ', null, 42]) {
      const response = await mutate(taskPath, 'PATCH', { title });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
      assert.deepEqual(await get(tasksPath), [completed, second]);
    }
    assert.equal((await mutate(`${otherTasksPath}/${task.id}`, 'PATCH', { title: 'Wrong project' })).status, 404);
    assert.equal((await mutate(`${tasksPath}/99999`, 'PATCH', { title: 'Missing' })).status, 404);
    assert.equal((await mutate(taskPath, 'PATCH', { title: 'Mixed', completed: false })).status, 400);
    const renamed = { ...completed, title: 'Renamed task' };
    const response = await mutate(taskPath, 'PATCH', { title: '  Renamed task  ' });
    assert.equal(response.status, 200);
    assert.deepEqual(await response.json(), renamed);
    assert.deepEqual(await get(tasksPath), [renamed, second]);
    assert.deepEqual(await get(otherTasksPath), []);
    assert.deepEqual(await get('/api/projects'), [summary, other]);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await get(tasksPath), [renamed, second]);
    await mutate(projectPath, 'PATCH', { archived: true });
    assert.equal((await mutate(taskPath, 'PATCH', { title: 'Forbidden' })).status, 409);
    assert.deepEqual(await get(tasksPath), [renamed, second]);
    await stop(running.child);
    running = await start(port, database);
    assert.equal((await mutate(taskPath, 'PATCH', { title: 'Still forbidden' })).status, 409);
    await mutate(projectPath, 'PATCH', { archived: false });
    const restored = { ...renamed, title: 'Restored task' };
    assert.deepEqual(await (await mutate(taskPath, 'PATCH', { title: ' Restored task ' })).json(), restored);
    const renamedOpen = { ...second, title: 'Renamed open task' };
    assert.deepEqual(await (await mutate(`${tasksPath}/${second.id}`, 'PATCH', { title: ' Renamed open task ' })).json(), renamedOpen);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await get(tasksPath), [restored, renamedOpen]);
    assert.deepEqual(await get('/api/projects'), [summary, other]);
    assert.deepEqual(await get(otherTasksPath), []);
  } finally {
    if (running && running.child.exitCode === null) await stop(running.child);
    await rm(directory, { recursive: true, force: true });
  }
});

test('legacy databases migrate without losing project IDs or tasks', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-migration-'));
  const database = join(directory, 'legacy.sqlite');
  const db = new DatabaseSync(database);
  db.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL,
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)));
    INSERT INTO projects (id, name) VALUES (42, 'Existing project');
    INSERT INTO tasks (project_id, title, completed) VALUES (42, 'Existing task', 1);`);
  db.close();
  let running;
  try {
    running = await start(await availablePort(), database);
    const projects = await (await fetch(`${running.base}/api/projects`)).json();
    assert.deepEqual(projects, [{ id: 42, name: 'Existing project', archived: false, completed: 1, total: 1 }]);
    const tasks = await (await fetch(`${running.base}/api/projects/42/tasks`)).json();
    assert.deepEqual(tasks, [{ id: 1, title: 'Existing task', completed: true }]);
  } finally {
    if (running && running.child.exitCode === null) await stop(running.child);
    await rm(directory, { recursive: true, force: true });
  }
});

test('projects and tasks validate, preserve ownership and order, and survive restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-'));
  const port = await availablePort();
  const database = join(directory, 'nested', 'projects.sqlite');
  let running;
  try {
    running = await start(port, database);
    const get = path => fetch(`${running.base}${path}`);
    const create = name => fetch(`${running.base}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    for (const name of ['', ' \t\n ', null]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    assert.equal(first.archived, false);
    assert.equal(first.completed, 0);
    assert.equal(first.total, 0);
    const second = await (await create('<Second project>')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    assert.equal((await get('/api/projects/99999')).status, 404);
    for (const path of ['/', `/projects/${first.id}`, '/app.js', '/style.css']) {
      assert.equal((await get(path)).status, 200);
    }
    const tasksPath = `/api/projects/${first.id}/tasks`;
    const otherTasksPath = `/api/projects/${second.id}/tasks`;
    const createTask = title => fetch(`${running.base}${tasksPath}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title }),
    });
    const completeTask = (path, completed) => fetch(`${running.base}${path}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ completed }),
    });
    assert.deepEqual(await (await get(tasksPath)).json(), []);
    for (const title of ['', ' \t\n ', null, 12]) {
      const response = await createTask(title);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await (await get(tasksPath)).json(), []);
    const taskResponse = await createTask('  First task  ');
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const secondTask = await (await createTask('<Second task>')).json();
    assert.deepEqual(await (await get(tasksPath)).json(), [task, secondTask]);
    assert.deepEqual(await (await get(otherTasksPath)).json(), []);
    assert.equal((await get('/api/projects/99999/tasks')).status, 404);
    assert.equal((await completeTask(`${otherTasksPath}/${task.id}`, true)).status, 404);
    assert.equal((await completeTask(`${tasksPath}/99999`, true)).status, 404);
    assert.equal((await completeTask(`${tasksPath}/${task.id}`, 'true')).status, 400);
    assert.deepEqual(await (await get(tasksPath)).json(), [task, secondTask]);
    const completed = { ...task, completed: true };
    assert.deepEqual(await (await completeTask(`${tasksPath}/${task.id}`, true)).json(), completed);
    assert.deepEqual(await (await completeTask(`${tasksPath}/${task.id}`, false)).json(), task);
    assert.deepEqual(await (await completeTask(`${tasksPath}/${task.id}`, true)).json(), completed);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await (await get(tasksPath)).json(), [completed, secondTask]);
    assert.deepEqual(await (await get(otherTasksPath)).json(), []);
    assert.equal((await get(`/projects/${first.id}`)).status, 200);
    const summary = { ...first, completed: 1, total: 2 };
    assert.deepEqual(await (await get('/api/projects')).json(), [summary, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), summary);
    const setArchived = archived => fetch(`${running.base}/api/projects/${first.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ archived }),
    });
    assert.equal((await setArchived('true')).status, 400);
    const archived = { ...summary, archived: true };
    assert.deepEqual(await (await setArchived(true)).json(), archived);
    assert.equal((await createTask('Forbidden')).status, 409);
    assert.equal((await completeTask(`${tasksPath}/${task.id}`, false)).status, 409);
    assert.deepEqual(await (await get(tasksPath)).json(), [completed, secondTask]);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await (await get('/api/projects')).json(), [archived, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), archived);
    assert.deepEqual(await (await setArchived(false)).json(), summary);
    assert.deepEqual(await (await get(tasksPath)).json(), [completed, secondTask]);
    assert.deepEqual(await (await completeTask(`${tasksPath}/${task.id}`, false)).json(), task);
    await stop(running.child);
    running = await start(port, database);
    assert.deepEqual(await (await get('/api/projects')).json(), [{ ...summary, completed: 0 }, second]);
    const malformed = await fetch(`${running.base}/api/projects`, { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
  } finally {
    if (running && running.child.exitCode === null) await stop(running.child);
    await rm(directory, { recursive: true, force: true });
  }
});

